  1	import { z } from 'zod';
  2	import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
  3	import { LedgerStore } from '../storage/ledger-store.js';
  4	import { loadRegistry, findByFolderName } from '../storage/repository-registry.js';
  5	import { KnowledgeStoreManager } from '../storage/knowledge-store.js';
  6	import { resolveLedgerRoot, deriveRepoName } from '../utils/ledger-root.js';
  7	import type { ProjectMeta } from '../schema/project-meta.js';
  8	import type { RepositoryEntry } from '../schema/repository-registry.js';
  9	import type { Insight } from '../schema/knowledge.js';
 10	
 11	// ─── Input Schema ─────────────────────────────────────────────────────────
 12	
 13	const GetRepositoryContextSchema = z.object({
 14	  cwd_path: z
 15	    .string()
 16	    .optional()
 17	    .describe(
 18	      'Absolute path to the workspace root directory. Used to derive the repository name ' +
 19	      'when repository_name is not provided. Ignored when repository_name is supplied.'
 20	    ),
 21	  repository_name: z
 22	    .string()
 23	    .optional()
 24	    .describe(
 25	      'Explicit repository name to look up in the registry. When provided, cwd_path ' +
 26	      'is not used for name derivation. Treated as both the ledger folder name and the ' +
 27	      'registry lookup key.'
 28	    ),
 29	  include_insights: z
 30	    .boolean()
 31	    .optional()
 32	    .default(true)
 33	    .describe(
 34	      'When true (default), the response includes relevant_insights[] queried from the ' +
 35	      'knowledge store. Set to false to return an empty relevant_insights[] array and reduce response size.'
 36	    ),
 37	  max_projects: z
 38	    .number()
 39	    .int()
 40	    .positive()
 41	    .optional()
 42	    .default(5)
 43	    .describe(
 44	      'Maximum number of projects to return in the projects[] array, sorted by date_created ' +
 45	      'descending (most recent first). Defaults to 5.'
 46	    ),
 47	});
 48	
 49	// ─── Response Shape ───────────────────────────────────────────────────────
 50	
 51	/**
 52	 * A single project entry returned in the projects[] array.
 53	 * Derived from ProjectMeta with a curated subset of fields.
 54	 */
 55	interface ProjectEntry {
 56	  slug: string;
 57	  plan_path: string;
 58	  status: string;
 59	  date_created: string;
 60	  last_updated: string;
 61	  title?: string;
 62	  outcome_summary: string | null;
 63	  progress_pct?: number;
 64	}
 65	
 66	/**
 67	 * The full structured response from ledger_get_repository_context.
 68	 */
 69	interface RepositoryContextResponse {
 70	  repository_name: string;
 71	  repository_id: string | null;
 72	  repository_label: string | null;
 73	  total_projects: number;
 74	  strategic_vision: RepositoryEntry['vision'] | null;
 75	  projects: ProjectEntry[];
 76	  relevant_insights: Insight[];
 77	}
 78	
 79	// ─── Handler ──────────────────────────────────────────────────────────────
 80	
 81	async function getRepositoryContext(
 82	  args: z.infer<typeof GetRepositoryContextSchema>
 83	): Promise<{ content: Array<{ type: 'text'; text: string }>; isError?: boolean }> {
 84	  try {
 85	    const ledgerRoot = resolveLedgerRoot();
 86	
 87	    // 1. Resolve repository name
 88	    let repositoryName: string;
 89	    if (args.repository_name) {
 90	      repositoryName = args.repository_name;
 91	    } else if (args.cwd_path) {
 92	      // Derive from the workspace path (same logic as LedgerStore constructor)
 93	      repositoryName = deriveRepoName(
 94	        // deriveRepoName expects a plan folder path — construct a synthetic one
 95	        // that places the repo root 4 levels above cwd_path (the conventional layout)
 96	        `${args.cwd_path}/docs/agents/plans/synthetic-slug`
 97	      );
 98	    } else {
 99	      return {
100	        content: [

101	          {
102	            type: 'text' as const,
103	            text: 'Error: Either cwd_path or repository_name must be provided.',
104	          },
105	        ],
106	        isError: true,
107	      };
108	    }
109	
110	    // 2. Consult the registry for this repository
111	    const registry = await loadRegistry(ledgerRoot);
112	    const registryEntry = findByFolderName(registry, repositoryName);
113	
114	    // 3. Collect folder names to scan
115	    //    - Registry match: scan ALL declared folder_names (cross-folder aggregation)
116	    //    - No registry match: scan only the single derived folder name
117	    const folderNamesToScan: string[] = registryEntry
118	      ? registryEntry.folder_names
119	      : [repositoryName];
120	
121	    // 4. Read projects from the targeted namespace directories only
122	    const allProjects = await LedgerStore.listProjectsByFolderNames(
123	      folderNamesToScan,
124	      ledgerRoot
125	    );
126	
127	    // 5. Sort by date_created descending (most recently created first)
128	    const sorted = [...allProjects].sort((a, b) =>
129	      b.date_created.localeCompare(a.date_created)
130	    );
131	
132	    const totalProjects = sorted.length;
133	
134	    // 6. Apply max_projects cap
135	    const maxProjects = args.max_projects ?? 5;
136	    const capped = sorted.slice(0, maxProjects);
137	
138	    // 7. Map to ProjectEntry shape
139	    const projects: ProjectEntry[] = capped.map((meta: ProjectMeta) => {
140	      const entry: ProjectEntry = {
141	        slug: meta.slug,
142	        plan_path: meta.plan_path,
143	        status: meta.status,
144	        date_created: meta.date_created,
145	        last_updated: meta.last_updated,
146	        outcome_summary: meta.outcome_summary ?? null,
147	      };
148	      if (meta.title !== undefined) {
149	        entry.title = meta.title;
150	      }
151	      if (meta.progress_pct !== undefined) {
152	        entry.progress_pct = meta.progress_pct;
153	      }
154	      return entry;
155	    });
156	
157	    // 8. Query knowledge store for relevant insights (optional)
158	    let relevantInsights: Insight[] = [];
159	    if (args.include_insights !== false) {
160	      const knowledgeManager = new KnowledgeStoreManager(ledgerRoot);
161	      // Query both global and repository-scoped insights
162	      const [globalInsights, repoInsights] = await Promise.all([
163	        knowledgeManager.listInsights({ scope: 'global', limit: 20 }),
164	        safeListRepositoryInsights(knowledgeManager, repositoryName),
165	      ]);
166	      // Deduplicate by insight id (global insights take precedence over repo-scoped)
167	      const seenIds = new Set<number>();
168	      const deduped: Insight[] = [];
169	      for (const insight of [...globalInsights, ...repoInsights]) {
170	        if (!seenIds.has(insight.id)) {
171	          seenIds.add(insight.id);
172	          deduped.push(insight);
173	        }
174	      }
175	      relevantInsights = deduped;
176	    }
177	
178	    // 9. Build the response
179	    const response: RepositoryContextResponse = {
180	      repository_name: repositoryName,
181	      repository_id: registryEntry ? registryEntry.id : null,
182	      repository_label: registryEntry ? registryEntry.label : null,
183	      total_projects: totalProjects,
184	      strategic_vision: registryEntry ? registryEntry.vision : null,
185	      projects,
186	      relevant_insights: relevantInsights,
187	    };
188	
189	    return {
190	      content: [
191	        {
192	          type: 'text' as const,
193	          text: JSON.stringify(response, null, 2),
194	        },
195	      ],
196	    };
197	  } catch (error) {
198	    return {
199	      content: [
200	        {
201	          type: 'text' as const,
202	          text: `Error retrieving repository context: ${(error as Error).message}`,
203	        },
204	      ],
205	      isError: true,
206	    };
207	  }
208	}
209	
210	/**
211	 * Safely lists repository-scoped insights for the given repository name.
212	 * Returns an empty array when the repository name fails the SLUG_REGEX check
213	 * (e.g. "unknown"), so callers do not need to guard against thrown errors.
214	 */
215	async function safeListRepositoryInsights(
216	  manager: KnowledgeStoreManager,
217	  repoName: string
218	): Promise<Insight[]> {
219	  try {
220	    return await manager.listInsights({ scope: 'repository', repository_name: repoName });
221	  } catch {
222	    return [];
223	  }
224	}
225	
226	// ─── Internal exports for testing ────────────────────────────────────────
227	
228	/**
229	 * @internal — exported for unit testing only. Follows the `_internal` naming convention.
230	 */
231	export const _internal = {
232	  GetRepositoryContextSchema,
233	  getRepositoryContext,
234	};
235	
236	// ─── Tool Registration ────────────────────────────────────────────────────
237	
238	export function register(server: McpServer): void {
239	  server.registerTool(
240	    'ledger_get_repository_context',
241	    {
242	      description:
243	        'Returns a compact project timeline with curated outcome summaries, relevant knowledge-base ' +
244	        'insights, and strategic vision for a repository. Gives the Planner agent access to prior ' +
245	        'project history within the same repository. OPTIONAL params: cwd_path (workspace root for ' +
246	        'auto-detecting the repository name), repository_name (explicit override), ' +
247	        'include_insights (default: true), max_projects (default: 5).',
248	      inputSchema: GetRepositoryContextSchema,
249	    },
250	    getRepositoryContext as any

  1	/**
  2	 * Integration tests for ledger_get_repository_context tool.
  3	 *
  4	 * Tests drive the tool handler directly via _internal, using vi.mock to
  5	 * redirect resolveLedgerRoot() and deriveRepoName() to controlled values
  6	 * so the real ledger storage is never touched.
  7	 */
  8	import { vi, describe, it, expect, beforeEach, afterEach } from 'vitest';
  9	import { mkdtemp, rm, mkdir, writeFile } from 'fs/promises';
 10	import { join } from 'path';
 11	import { tmpdir } from 'os';
 12	
 13	// ─── Module-level variable updated by beforeEach ──────────────────────────
 14	let tempLedgerRoot: string;
 15	
 16	vi.mock('../../src/utils/ledger-root.js', () => ({
 17	  resolveLedgerRoot: () => tempLedgerRoot,
 18	  WORKSPACE_ROOT: '/fake/workspace',
 19	  ORCHESTRATOR_LOGS_DIR: '/fake/workspace/orchestrator/logs',
 20	  projectSlugFromPath: (p: string) => (p.split('/').pop() ?? 'unknown'),
 21	  inferProjectRootFromPlanPath: (p: string) => {
 22	    // Walk up 4 dirs from the plan path
 23	    const parts = p.split('/');
 24	    return parts.slice(0, parts.length - 4).join('/') || '/';
 25	  },
 26	  deriveRepoName: (_planPath: string) => 'my-repo',
 27	}));
 28	
 29	import { _internal } from '../../src/tools/repository-context.js';
 30	
 31	const { getRepositoryContext } = _internal;
 32	
 33	// ─── Helpers ──────────────────────────────────────────────────────────────
 34	
 35	function parseResult(result: { content: Array<{ type: string; text: string }> }) {
 36	  return JSON.parse(result.content[0]!.text);
 37	}
 38	
 39	function isError(result: { isError?: boolean }) {
 40	  return result.isError === true;
 41	}
 42	
 43	/**
 44	 * Seeds a minimal .meta.json for a project at:
 45	 * {tempLedgerRoot}/{folder}/{slug}/.meta.json
 46	 */
 47	async function seedProject(
 48	  folder: string,
 49	  slug: string,
 50	  overrides: Record<string, unknown> = {}
 51	): Promise<void> {
 52	  const dir = join(tempLedgerRoot, folder, slug);
 53	  await mkdir(dir, { recursive: true });
 54	  const meta = {
 55	    slug,
 56	    plan_path: `/fake/${folder}/docs/agents/plans/${slug}`,
 57	    status: 'COMPLETE',
 58	    date_created: overrides.date_created ?? '2026-01-01T00:00:00Z',
 59	    last_updated: overrides.last_updated ?? '2026-01-01T00:00:00Z',
 60	    ...overrides,
 61	  };
 62	  await writeFile(join(dir, '.meta.json'), JSON.stringify(meta, null, 2), 'utf-8');
 63	}
 64	
 65	/**
 66	 * Seeds .repositories.json in the ledger root.
 67	 */
 68	async function seedRegistry(data: unknown): Promise<void> {
 69	  await writeFile(
 70	    join(tempLedgerRoot, '.repositories.json'),
 71	    JSON.stringify(data, null, 2),
 72	    'utf-8'
 73	  );
 74	}
 75	
 76	// ─── Setup / Teardown ─────────────────────────────────────────────────────
 77	
 78	beforeEach(async () => {
 79	  tempLedgerRoot = await mkdtemp(join(tmpdir(), 'repo-ctx-test-'));
 80	});
 81	
 82	afterEach(async () => {
 83	  await rm(tempLedgerRoot, { recursive: true, force: true });
 84	});
 85	
 86	// ─── Basic response shape ──────────────────────────────────────────────────
 87	
 88	describe('ledger_get_repository_context — response shape', () => {
 89	  it('returns all required top-level fields in the response', async () => {
 90	    const result = await getRepositoryContext({
 91	      repository_name: 'my-repo',
 92	      include_insights: false,
 93	    });
 94	
 95	    expect(isError(result as any)).toBe(false);
 96	    const data = parseResult(result as any);
 97	
 98	    expect(data).toHaveProperty('repository_name');
 99	    expect(data).toHaveProperty('repository_id');
100	    expect(data).toHaveProperty('repository_label');

101	    expect(data).toHaveProperty('total_projects');
102	    expect(data).toHaveProperty('strategic_vision');
103	    expect(data).toHaveProperty('projects');
104	    expect(data).toHaveProperty('relevant_insights');
105	  });
106	
107	  it('returns the correct repository_name from input', async () => {
108	    const result = await getRepositoryContext({
109	      repository_name: 'my-repo',
110	      include_insights: false,
111	    });
112	    const data = parseResult(result as any);
113	    expect(data.repository_name).toBe('my-repo');
114	  });
115	});
116	
117	// ─── No registry match ────────────────────────────────────────────────────
118	
119	describe('ledger_get_repository_context — no registry match', () => {
120	  it('returns null for repository_id, repository_label, and strategic_vision when no registry file exists', async () => {
121	    await seedProject('my-repo', '2026-01-01-project-alpha');
122	
123	    const result = await getRepositoryContext({
124	      repository_name: 'my-repo',
125	      include_insights: false,
126	    });
127	
